import numpy as np
def run(w,K):
    cols=[np.ones_like(t),x,v,x**2,x*v,v**2,x**3,x**2*v,x*v**2,v**3]
    for k in range(1,K+1):
        cols+= [np.cos(k*w*t), np.sin(k*w*t)]
    cols+=[x*np.cos(w*t),x*np.sin(w*t),v*np.cos(w*t),v*np.sin(w*t)]
    X=np.column_stack(cols)
    c=np.linalg.lstsq(X,dv_dt,rcond=None)[0]
    return np.mean((X@c-dv_dt)**2)/np.var(dv_dt), c
for K in [1,2,3,4]:
    best=None
    for w in np.linspace(0.3,0.45,301):
        e,c=run(w,K)
        if best is None or e<best[0]: best=(e,w,c)
    print(K,best[0],best[1])
print(np.round(best[2],4))

